B=[]
def pages(text):
 out=[]
 for line in text.strip().split('\n'):
  who,body=line.split('|',1);out.append({'speaker':int(who),'text':body})
 return out
def actor(cid,side=0,x=4,y=4,level=12,skills=None,**kw):
 a={'id':cid,'side':side,'x':x,'y':y,'level':level,**kw}
 if skills is not None:a['skills']=list(dict.fromkeys(([] if cid==47 else [5])+[s for s in skills if s!=41 or cid in (12,47)]))
 return a
